 directory.onclick=e=>{const row=e.target.closest('[data-map-open]');if(!row)return;e.stopPropagation();directory.open=false;void open(row.dataset.mapOpen).catch(fail);};
 directory.oncontextmenu=e=>{const row=e.target.closest('[data-map-open],[data-map-current]');if(!row)return;e.preventDefault();e.stopPropagation();const id=row.dataset.mapOpen||row.dataset.mapCurrent;if(!id)return;void(async()=>{const answer=await menu([{value:'rename',label:'重命名'},{value:'delete',label:'删除地图',danger:true}],{clientX:e.clientX,clientY:e.clientY});if(['rename','delete'].includes(answer.value)){directory.open=false;await command(id,answer.value);}})().catch(fail);};
